mapper.select:
SELECT
  APKIHONCD,
  SHOPCD,
  RENBAN,
  DSPLYKBN
FROM
  S02M044T
WHERE
  APKIHONCD = #{apkihoncd, jdbcType=VARCHAR}
  AND SHOPCD = #{shopcd, jdbcType=VARCHAR}
  AND RENBAN = #{renban, jdbcType=NUMERIC}
  AND KSHNSYSTMYMD = #{kshnsystmymd, jdbcType=VARCHAR}
  AND KSHNSYSTMJIKAN = #{kshnsystmjikan, jdbcType=VARCHAR}
FOR UPDATE

SELECT SHMV.SHNAPKIHONCD , SHMV.SHNCD , SHMV.STKBN , SHMV.LCTGRYCD , SHMV.MCTGRYCD , SHMV.SCTGRYCD , CASE WHEN SHMV.SHNNMKIRIKAEDD <= #{dlvryytidd,jdbcType=VARCHAR} THEN SHMV.SHINSHNNMRYAKUSHO ELSE SHMV.GENZSHNNMRYAKUSHO END SHNNMRYAKUSHO , CASE WHEN SHMV.HYOJUNPRICEKIRIKAEDD <= #{dlvryytidd,jdbcType=VARCHAR} THEN SHMV.SHINPRICEKBN ELSE SHMV.GENZPRICEKBN END PRICEKBN , SHMV.HYOJUNPRICEKIRIKAEDD , SHMV.GENZHYOJUNPRICE , SHMV.SHINHYOJUNPRICE , SHMV.GENZMOCHIKAERIPRICE , SHMV.SHINMOCHIKAERIPRICE , SHMV.OPNPRICEKIRIKAEDD , SHMV.GENZOPNPRICE , SHMV.SHINOPNPRICE , SHMV.GENZOPNMOCHIKAERIPRICE , SHMV.SHINOPNMOCHIKAERIPRICE , SHMV.HANSOKUNM , SHMV.HANSOKUKBN , SHMV.HANSOKUSTRTDD , SHMV.HANSOKUSHRYDD , SHMV.HANSOKUDLVRYPRICE , SHMV.HANSOKUMOCHIKAERIPRICE , SHMV.HANSOKUYUSENKBN , SHMV.ZAIKOUNT , SHMV.IRO , SHMV.SZNM SZ , SHMV.URITRTSKITANINM URITRTSKITANI , SHMV.URIIRISU , SHMV.URITANINM URITANI , SHMV.TAXSETTEIKBN , SHMV.TAXKBN , SHMV.ZAIKOARAMUSURYO , SHMV.TRTSKIKBN , TKSM.TOKUBETSUUNTKBN , TSTM.TEKIYOSTRTDD , TSTM.TEKIYOSHRYDD , TSTM.DLVRYPRICE , TSTM.MOCHIKAERIPRICE , CASE WHEN SHMV.SHNNMKIRIKAEDD <= #{dlvryytidd,jdbcType=VARCHAR} THEN SHMV.SHINSHNNM ELSE SHMV.GENZSHNNM END SHNNM , CASE WHEN SHMV.HYOJUNPRICEKIRIKAEDD <= #{dlvryytidd,jdbcType=VARCHAR} THEN SHMV.SHINHYOJUNPRICE ELSE SHMV.GENZHYOJUNPRICE END HYOJUNPRICE , TSUM.TEKIYOSTRTDD AS SET_TEKIYOSTRTDD , TSUM.TEKIYOSHRYDD AS SET_TEKIYOSHRYDD , TSUM.DLVRYPRICE AS SET_DLVRYPRICE , TSUM.MOCHIKAERIPRICE AS SET_MOCHIKAERIPRICE , TKSM.RKNKINDTOKUBETSUUNTFLG , TJMM.KEIJOKBN , TJMM.KATASIKI , TJMM.HANSOKUTAIOU , TJMM.SURYO AS ACPTSURYO , TJMM.MEISAIBIKO FROM
S02M049T TJMM
S02M056T TJMM
INNER JOIN S02V001T SHMV ON(SHMV.APKIHONCD = TJMM.APKIHONCD AND SHMV.SHOPCD = TJMM.SHOPCD AND SHMV.SHNCD = TJMM.SHNCD AND SHMV.SHOPYUKOKBN = '1' ) LEFT OUTER JOIN S02M013T TKSM ON ( TKSM.APKIHONCD = SHMV.APKIHONCD AND TKSM.SHOPCD = SHMV.SHOPCD AND TKSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M009T TSTM ON ( TSTM.APKIHONCD = SHMV.APKIHONCD AND TSTM.SHOPCD = SHMV.SHOPCD AND TSTM.SHNCD = SHMV.SHNCD AND TSTM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} AND #{dlvryytidd,jdbcType=VARCHAR} BETWEEN TSTM.TEKIYOSTRTDD AND TSTM.TEKIYOSHRYDD AND TSTM.YUKOKBN = '1' ) LEFT OUTER JOIN S02M066T TSUM ON ( TSUM.APKIHONCD = SHMV.APKIHONCD AND TSUM.SHOPCD = SHMV.SHOPCD AND TSUM.STSHNCD = SHMV.SHNCD AND TSUM.TOKUISAKICD = TKSM.TOKUISAKICD AND #{dlvryytidd,jdbcType=VARCHAR} BETWEEN TSUM.TEKIYOSTRTDD AND TSUM.TEKIYOSHRYDD AND TSUM.YUKOKBN = '1' ) WHERE TJMM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TJMM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TJMM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND TJMM.DLVRYSHUU = #{dlvryshuu,jdbcType=VARCHAR} AND TJMM.SHITEIYOBI = #{shiteiyobi,jdbcType=VARCHAR}
AND TJMM.SHITEIKBN = #{shiteikbn,jdbcType=VARCHAR} AND TJMM.SHITEIYOUSO = #{shiteiyouso,jdbcType=VARCHAR}
AND TJMM.YUKOKBN = '1' ORDER BY TJMM.RENBAN
